const embeddedImages = {"1209-I-12.png":"data:image/png;base64,","1209-I-4.png":"data:image/png;base64,","1209-I-7.png":"data:image/png;base64,","1209-III-1.png":"data:image/png;base64,","1209-III-6.png":"data:image/png;base64,","1210-I-4.png":"data:image/png;base64,","1210-I-5.png":"data:image/png;base64,","1210-I-8.png":"data:image/png;base64,","1210-I-9.png":"data:image/png;base64,","1210-III-1.png":"data:image/png;base64,","1210-III-6.png":"data:image/png;base64,"};
const NOTE = 'Đáp án mặc định theo yêu cầu nhập liệu, chưa xác minh: trắc nghiệm A; mọi mệnh đề Đúng; trả lời ngắn 2.7. Không có lời giải.';
const idFor = key => new mongoose.Types.ObjectId(crypto.createHash('sha256').update('thpt-lg1-2026-l1:' + key).digest('hex').slice(0, 24));
const escape = text => String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
function richText(text, image) {
  const ops = []; let html = '';
  const pieces = text.split('$');
  if (pieces.length % 2 === 0) throw new Error('Thiếu dấu đóng công thức: ' + text);
  pieces.forEach((piece, i) => {
    if (!piece) return;
    if (i % 2) {
      ops.push({ insert: { formula: piece } });
      html += `<span class="ql-formula" data-value="${escape(piece)}">${escape(piece)}</span>`;
    } else { ops.push({ insert: piece }); html += escape(piece); }
  });
  ops.push({ insert: '\n' }); html = `<p>${html}</p>`;
  if (image) {
    const src = embeddedImages[image];
    if (!src) throw new Error("Thiếu ảnh nhúng: " + image);
    ops.push({ insert: { image: src } }, { insert: '\n' });
    html += `<p><img src="${src}" alt="Hình minh họa từ đề gốc" style="max-width:100%;height:auto"></p>`;
  }
  return { html, delta: { ops } };
}
function buildSeedData(adminId, subjectId, topicId, codes = ['1209', '1210']) {
  return data.exams.filter(exam => codes.includes(exam.code)).map(exam => {
    const questions = exam.questions.map(q => ({
      _id: idFor(`${exam.code}:${q.part}:${q.number}`), subjectId, topicId, createdBy: adminId,
      scope: 'system', published: false, bloomLevel: 3, type: q.type,
      content: richText(`Phần ${q.part} – Câu ${q.number}. ${q.text}`, q.image),
      contentText: `[LG1 ${exam.code} ${q.part}.${q.number}] ${q.text.replace(/\$/g, '')}`,
      options: (q.options || []).map((text, i) => ({ key: (q.type === 'truefalse' ? 'abcd' : 'ABCD')[i],
        content: richText(text), isCorrect: q.type === 'truefalse' ? true : null })),
      correctAnswer: q.type === 'mcq' ? 'A' : '',
      acceptedAnswers: q.type === 'fill' ? ['2.7'] : [],
      explanation: richText(NOTE),
    }));
    return { code: exam.code, questions, exam: {
      _id: idFor(`exam:${exam.code}`), title: exam.title, subjectId, createdBy: adminId,
      duration: exam.duration, scope: 'system', status: 'draft', groupIds: [],
      description: 'Mã đề ' + exam.code + '. ' + NOTE,
      questionIds: questions.map(q => q._id),
    } };
  });
}
async function validate(batches) {
  for (const batch of batches) {
    if (batch.questions.length !== 22) throw new Error('Mỗi mã đề phải có 22 câu.');
    for (const question of batch.questions) {
      await new Question(question).validate();
      const count = question.options.length;
      if (count !== (question.type === 'fill' ? 0 : 4)) throw new Error('Sai số lựa chọn.');
    }
    await new Exam(batch.exam).validate();
  }
  for (const exam of data.exams) for (const q of exam.questions) {
    if (q.image && !embeddedImages[q.image]) {
      throw new Error('Thiếu hình: ' + q.image);
    }
  }
}
async function main() {
  const { values } = parseArgs({ options: { 'validate-only': { type: 'boolean', default: false },
    'admin-email': { type: 'string' }, code: { type: 'string' } } });
  const codes = values.code ? [values.code] : ['1209', '1210'];
  if (codes.some(code => !['1209', '1210'].includes(code))) throw new Error('--code chỉ nhận 1209 hoặc 1210.');
  const fakeId = idFor('validation');
  await validate(buildSeedData(fakeId, fakeId, fakeId, codes));
  if (values['validate-only']) {
    console.log(`Kiểm tra đạt: ${codes.length} đề, ${codes.length * 22} câu; schema, công thức có cặp dấu và 11 ảnh nhúng hợp lệ. Chưa kết nối database.`);
    return;
  }
  require('dotenv').config({ path: path.join(__dirname, '../.env'), quiet: true });
  if (!process.env.MONGO_URI) throw new Error('Thiếu MONGO_URI trong .env hoặc biến môi trường.');
  await mongoose.connect(process.env.MONGO_URI);
  let admin;
  if (values['admin-email']) {
    admin = await Account.findOne({ email: values['admin-email'].trim().toLowerCase(), role: 'admin', status: 'active' });
  } else {
    const admins = await Account.find({ role: 'admin', status: 'active' }).limit(2);
    if (admins.length > 1) throw new Error('Có nhiều admin. Hãy chỉ định --admin-email email-cua-ban.');
    admin = admins[0];
  }
  if (!admin) throw new Error('Không tìm thấy admin hoạt động. Tạo tài khoản admin trước khi import.');
  let subject = await Subject.findOne({ code: 'TOAN' });
  if (!subject) subject = await Subject.findOne({ name: /^Toán(?: học)?$/i });
  if (!subject) subject = await Subject.findOneAndUpdate({ code: 'TOAN' }, { $setOnInsert: {
    name: 'Toán', code: 'TOAN', description: 'Môn Toán THPT', active: true,
  } }, { upsert: true, new: true, runValidators: true, setDefaultsOnInsert: true });
  const topic = await Topic.findOneAndUpdate({ subjectId: subject._id, code: 'LG1_2026_L1' }, { $setOnInsert: {
    subjectId: subject._id, code: 'LG1_2026_L1', name: 'Đề Lạng Giang số 1 lần 1 năm 2026–2027',
    description: 'Nhập từ PDF, mã 1209 và 1210. ' + NOTE, active: true,
  } }, { upsert: true, new: true, runValidators: true, setDefaultsOnInsert: true });
  const batches = buildSeedData(admin._id, subject._id, topic._id, codes);
  await validate(batches);
  for (const batch of batches) {
    if (await Exam.exists({ _id: batch.exam._id })) {
      console.log(`Bỏ qua mã ${batch.code}: đã import, giữ nguyên mọi chỉnh sửa.`); continue;
    }
    // Stable ids + setOnInsert allow reruns after interruption without duplicates or overwrites.
    for (const question of batch.questions) {
      await Question.updateOne({ _id: question._id }, { $setOnInsert: { ...question, createdAt: new Date(), updatedAt: new Date() } }, { upsert: true, runValidators: true, timestamps: false });
    }
    const result = await Exam.updateOne({ _id: batch.exam._id }, { $setOnInsert: { ...batch.exam, createdAt: new Date(), updatedAt: new Date() } }, { upsert: true, runValidators: true, timestamps: false });
    console.log(`${result.upsertedCount ? 'Đã import' : 'Đã tồn tại'} mã ${batch.code}: 22 câu, 90 phút, đề nháp phía admin.`);
  }
  console.log(NOTE);
}
if (require.main === module) main().catch(error => {
  // Do not print database connection strings or credentials in errors.
  console.error('Seed thất bại:', error.name === 'MongoServerSelectionError' ? 'Không kết nối được MongoDB. Kiểm tra cấu hình kết nối.' : error.message);
  process.exitCode = 1;
}).finally(() => mongoose.disconnect());
module.exports = { data, richText, buildSeedData, validate, idFor };
